query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// PostgreSQL-only metric: no engine marker needed.
// deadlock_count is a DELTA metric (deadlocks per 60 s sample): SUM(SUM_OVER_TIME)
// gives an exact total across fragments. Never use RATE() on DELTA metrics.
| STATS deadlocks = SUM(SUM_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/deadlock_count`))
    BY database_id, attributes.database

breach.segment:
// Keep the source attribute name (no RENAME): alert grouping uses this column,
// and some rule-creation paths map grouping back to the source field.
// Alert threshold: deadlocks per database within the rule window.
// Isolated deadlocks are resolved by PostgreSQL (one transaction is aborted);
// a burst indicates conflicting lock ordering in application code.
// Set to >= 1 to be notified of every deadlock.
WHERE deadlocks >= 5
| KEEP database_id, attributes.database, deadlocks
| SORT deadlocks DESC
| LIMIT 100
